/* @lc app=leetcode id=3356 lang=kotlin */ class Solution { fun ok(nums: IntArray, qs: Array<IntArray>, k: Int): Boolean = LongArray(nums.size + 1).also { d -> qs.take(k).forEach { q -> d.set(q[0], d[q[0]] + q[2]).also { d[q[1] + 1] -= q[2].toLong() } } }.runningFold(0L) { a, b -> a + b }.drop(1).zip(nums.asList()) { c, v -> c >= v }.all { it } fun minZeroArray(nums: IntArray, queries: Array<IntArray>): Int = if (!ok(nums, queries, queries.size)) -1 else generateSequence(0 to queries.size) { (lo, hi) -> if (lo >= hi) null else ((lo + hi) / 2).let { mid -> if (ok(nums, queries, mid)) lo to mid else mid + 1 to hi } }.last().first }